const { createServer } = await import("./server.js");
const { generatedTools } = await import("./generated/tools.js");

function countByTags(tags: string[]): number {
  const wanted = new Set(tags.map((tag) => tag.toLowerCase()));
  return generatedTools.filter((tool) => wanted.has(tool.tag.toLowerCase())).length;
}

describe("MCP server tools/list", () => {
  const toolsetEnvVars = ["DOKPLOY_ENABLED_TAGS", "DOKPLOY_DISABLED_TAGS", "DOKPLOY_TOOL_PRESET"];

  afterEach(() => {
    for (const envVar of toolsetEnvVars) {
      delete process.env[envVar];
    }
  });

  async function getToolList() {
    const server = createServer();
    const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
    await server.connect(serverTransport);
    const client = new Client({ name: "test-client", version: "1.0.0" });
    await client.connect(clientTransport);
    const { tools } = await client.listTools();
    await client.close();
    return tools;
  }

  it("returns tools", async () => {
    const tools = await getToolList();
    expect(tools.length).toBeGreaterThan(0);
  });

  it("returns all tools by default", async () => {
    const tools = await getToolList();
    expect(tools).toHaveLength(generatedTools.length);
  });

  it("supports DOKPLOY_TOOL_PRESET=minimal for clients sensitive to large toolsets", async () => {
    process.env.DOKPLOY_TOOL_PRESET = "minimal";

    const tools = await getToolList();
    const tags = new Set(tools.map((tool) => tool.name.split("-")[0]));

    expect(tools).toHaveLength(countByTags(["project", "application"]));
    expect(tags).toEqual(new Set(["application", "project"]));
  });

  it("supports DOKPLOY_TOOL_PRESET=core for common application workflows", async () => {
    process.env.DOKPLOY_TOOL_PRESET = "core";

    const tools = await getToolList();
    const tags = new Set(tools.map((tool) => tool.name.split("-")[0]));

    expect(tools).toHaveLength(countByTags(["project", "server", "application"]));
    expect(tags).toEqual(new Set(["application", "project", "server"]));
  });

  it("lets DOKPLOY_ENABLED_TAGS override presets", async () => {
    process.env.DOKPLOY_TOOL_PRESET = "core";
    process.env.DOKPLOY_ENABLED_TAGS = "project,application";

    const tools = await getToolList();
    const tags = new Set(tools.map((tool) => tool.name.split("-")[0]));

    expect(tools).toHaveLength(countByTags(["project", "application"]));
    expect(tags).toEqual(new Set(["application", "project"]));
  });

  it("excludes DOKPLOY_DISABLED_TAGS after selecting tools", async () => {
    process.env.DOKPLOY_TOOL_PRESET = "deploy";
    process.env.DOKPLOY_DISABLED_TAGS = "domain,deployment";

    const tools = await getToolList();
    const tags = new Set(tools.map((tool) => tool.name.split("-")[0]));

    expect(tools).toHaveLength(
      countByTags(["project", "environment", "server", "application", "compose"]),
    );
    expect(tags.has("domain")).toBe(false);
    expect(tags.has("deployment")).toBe(false);
  });

  it("falls back to all tools for an unknown preset", async () => {
    process.env.DOKPLOY_TOOL_PRESET = "unknown";

    const tools = await getToolList();

    expect(tools).toHaveLength(generatedTools.length);
  });

  it("every tool inputSchema has $schema set to draft 2020-12", async () => {
    const tools = await getToolList();
    for (const tool of tools) {
      const schema = tool.inputSchema as Record<string, unknown>;
      expect(schema.$schema, `Tool "${tool.name}" is missing $schema or has wrong draft`).toBe(
        "https://json-schema.org/draft/2020-12/schema",
      );
    }
  });

  it("no tool inputSchema contains any $schema key at nested levels", async () => {
    const tools = await getToolList();

    function findNestedSchemaKeys(obj: unknown, path = ""): string[] {
      if (obj === null || typeof obj !== "object") return [];
      if (Array.isArray(obj)) {
        return obj.flatMap((item, i) => findNestedSchemaKeys(item, `${path}[${i}]`));
      }
      const record = obj as Record<string, unknown>;
      const found: string[] = [];
      for (const [key, value] of Object.entries(record)) {
        const currentPath = path ? `${path}.${key}` : key;
        if (key === "$schema" && path !== "") found.push(currentPath);
        found.push(...findNestedSchemaKeys(value, currentPath));
      }
      return found;
    }

    for (const tool of tools) {
      const found = findNestedSchemaKeys(tool.inputSchema);
      expect(
        found,
        `Tool "${tool.name}" has nested $schema keys at: ${found.join(", ")}`,
      ).toHaveLength(0);
    }
  });

  it("no tool inputSchema exposes regex lookaround patterns", async () => {
    const tools = await getToolList();

    function findLookaroundPatterns(obj: unknown, path = ""): string[] {
      if (obj === null || typeof obj !== "object") return [];
      if (Array.isArray(obj)) {
        return obj.flatMap((item, i) => findLookaroundPatterns(item, `${path}[${i}]`));
      }

      const record = obj as Record<string, unknown>;
      const found: string[] = [];
      for (const [key, value] of Object.entries(record)) {
        const currentPath = path ? `${path}.${key}` : key;
        if (key === "pattern" && typeof value === "string" && /\(\?<?[=!]/.test(value)) {
          found.push(currentPath);
        }
        found.push(...findLookaroundPatterns(value, currentPath));
      }
      return found;
    }

    for (const tool of tools) {
      const found = findLookaroundPatterns(tool.inputSchema);
      expect(
        found,
        `Tool "${tool.name}" exposes provider-incompatible lookaround patterns at: ${found.join(", ")}`,
      ).toHaveLength(0);
    }
  });

  it("no tool inputSchema exposes patterns invalid under strict regex syntax", async () => {
    const tools = await getToolList();

    function findStrictInvalidPatterns(obj: unknown, path = ""): string[] {
      if (obj === null || typeof obj !== "object") return [];
      if (Array.isArray(obj)) {
        return obj.flatMap((item, i) => findStrictInvalidPatterns(item, `${path}[${i}]`));
      }

      const record = obj as Record<string, unknown>;
      const found: string[] = [];
      for (const [key, value] of Object.entries(record)) {
        const currentPath = path ? `${path}.${key}` : key;
        if (key === "pattern" && typeof value === "string") {
          try {
            new RegExp(value, "v");
          } catch {
            found.push(`${currentPath}: ${value}`);
          }
        }
        found.push(...findStrictInvalidPatterns(value, currentPath));
      }
      return found;
    }

    for (const tool of tools) {
      const found = findStrictInvalidPatterns(tool.inputSchema);
      expect(
        found,
        `Tool "${tool.name}" exposes provider-incompatible patterns at: ${found.join(", ")}`,
      ).toHaveLength(0);
    }
  });

  it("all tools have name, inputSchema with type=object", async () => {
    const tools = await getToolList();
    for (const tool of tools) {
      expect(tool.name, "tool is missing name").toBeTruthy();
      expect(tool.inputSchema, `tool "${tool.name}" is missing inputSchema`).toBeDefined();
      expect(
        (tool.inputSchema as Record<string, unknown>).type,
        `tool "${tool.name}" inputSchema is missing type`,
      ).toBe("object");
    }
  });
});

import { describe, expect, it } from "vitest";
import { ResponseFormatter } from "./responseFormatter.js";

describe("ResponseFormatter.success", () => {
  it("returns success true and message when no data", () => {
    const result = ResponseFormatter.success("done");
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.success).toBe(true);
    expect(parsed.message).toBe("done");
    expect(parsed.data).toBeUndefined();
  });

  it("includes string data (readLogs response)", () => {
    const logs = "2024-01-01 INFO app started\n2024-01-01 INFO listening on :3000";
    const result = ResponseFormatter.success("application-readLogs completed successfully", logs);
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toBe(logs);
  });

  it("includes object data", () => {
    const data = { applicationId: "abc", status: "running" };
    const result = ResponseFormatter.success("ok", data);
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toEqual(data);
  });

  it("includes numeric data", () => {
    const result = ResponseFormatter.success("ok", 42);
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toBe(42);
  });

  it("includes boolean data", () => {
    const result = ResponseFormatter.success("ok", false);
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toBe(false);
  });

  it("omits data when null", () => {
    const result = ResponseFormatter.success("ok", null);
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toBeUndefined();
  });

  it("omits data when undefined", () => {
    const result = ResponseFormatter.success("ok", undefined);
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toBeUndefined();
  });

  it("includes empty string data", () => {
    const result = ResponseFormatter.success("ok", "");
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.data).toBe("");
  });

  it("is not marked as error", () => {
    const result = ResponseFormatter.success("ok");
    expect(result.isError).toBeUndefined();
  });
});

describe("ResponseFormatter.error", () => {
  it("returns success false and error message", () => {
    const result = ResponseFormatter.error("something went wrong");
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.success).toBe(false);
    expect(parsed.error).toBe("something went wrong");
    expect(parsed.details).toBeUndefined();
  });

  it("includes details when provided", () => {
    const result = ResponseFormatter.error("failed", "timeout after 30s");
    const parsed = JSON.parse(result.content[0].text);
    expect(parsed.details).toBe("timeout after 30s");
  });

  it("is marked as error", () => {
    const result = ResponseFormatter.error("failed");
    expect(result.isError).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import { DEFAULT_REDACTED_FIELDS, redactSensitive } from "./redactSensitive.js";

const redact = <T>(data: T) => redactSensitive(data, DEFAULT_REDACTED_FIELDS);

describe("redactSensitive", () => {
  it("redacts exact default field names", () => {
    const result = redact({ password: "hunter2", env: "KEY=value", apiKey: "sk-123" });
    expect(result).toEqual({ password: "[REDACTED]", env: "[REDACTED]", apiKey: "[REDACTED]" });
  });

  it("redacts provider-prefixed secret fields (issue #65)", () => {
    const result = redact({
      githubPrivateKey: "-----BEGIN RSA PRIVATE KEY-----",
      githubClientSecret: "ghs_abc",
      githubWebhookSecret: "whsec_abc",
      gitlabAccessToken: "glpat-abc",
      awsSecretAccessKey: "aws-abc",
    });
    expect(result).toEqual({
      githubPrivateKey: "[REDACTED]",
      githubClientSecret: "[REDACTED]",
      githubWebhookSecret: "[REDACTED]",
      gitlabAccessToken: "[REDACTED]",
      awsSecretAccessKey: "[REDACTED]",
    });
  });

  it("matches case-insensitively", () => {
    const result = redact({ PASSWORD: "x", GithubPrivateKey: "y" });
    expect(result).toEqual({ PASSWORD: "[REDACTED]", GithubPrivateKey: "[REDACTED]" });
  });

  it("preserves null and undefined values in sensitive fields", () => {
    const result = redact({ password: null, token: undefined });
    expect(result).toEqual({ password: null, token: undefined });
  });

  it("redacts inside nested objects and arrays", () => {
    const result = redact({
      apps: [{ name: "web", env: "SECRET=1" }, { config: { registryPassword: "p" } }],
    });
    expect(result).toEqual({
      apps: [
        { name: "web", env: "[REDACTED]" },
        { config: { registryPassword: "[REDACTED]" } },
      ],
    });
  });

  it("leaves non-sensitive fields untouched", () => {
    const data = { appName: "web", domain: "example.com", port: 3000, https: true };
    expect(redact(data)).toEqual(data);
  });

  it("returns data unchanged when the field list is empty", () => {
    const data = { password: "visible" };
    expect(redactSensitive(data, [])).toBe(data);
  });

  it("supports custom field lists via suffix match", () => {
    const result = redactSensitive({ myCustomField: "x", other: "y" }, ["customField"]);
    expect(result).toEqual({ myCustomField: "[REDACTED]", other: "y" });
  });

  it("does not hang on circular structures", () => {
    const data: Record<string, unknown> = { name: "a" };
    data.self = data;
    expect(() => redact(data)).not.toThrow();
  });

  it("drops prototype-pollution keys", () => {
    const data = JSON.parse('{"__proto__": {"polluted": true}, "name": "safe"}');
    const result = redact(data) as Record<string, unknown>;
    expect(Object.keys(result)).toEqual(["name"]);
  });

  // Known, accepted collateral of suffix matching: flag-style keys that end in a
  // sensitive word (e.g. isSecret) are also redacted. Erring toward redaction is
  // intentional for security-sensitive output.
  it("redacts flag-like keys ending in a sensitive suffix", () => {
    const result = redact({ isSecret: true });
    expect(result).toEqual({ isSecret: "[REDACTED]" });
  });
});

import { describe, expect, it } from "vitest";
import { parseCustomHeaders } from "./clientConfig.js";

describe("parseCustomHeaders", () => {
  it("returns no custom headers when unset", () => {
    expect(parseCustomHeaders(undefined)).toEqual({});
  });

  it("accepts Cloudflare Access-style headers", () => {
    const headers = parseCustomHeaders(
      JSON.stringify({
        "CF-Access-Client-Id": "client-id-placeholder",
        "CF-Access-Client-Secret": "client-secret-placeholder",
      }),
    );

    expect(headers).toEqual({
      "CF-Access-Client-Id": "client-id-placeholder",
      "CF-Access-Client-Secret": "client-secret-placeholder",
    });
  });

  it("rejects malformed JSON", () => {
    expect(() => parseCustomHeaders("not-json")).toThrow(/must be valid JSON/);
  });

  it("rejects an empty string when configured", () => {
    expect(() => parseCustomHeaders("")).toThrow(/must be valid JSON/);
  });

  it("rejects arrays", () => {
    expect(() => parseCustomHeaders("[]")).toThrow(/must be a JSON object/);
  });

  it("rejects non-object JSON", () => {
    expect(() => parseCustomHeaders('"header-value"')).toThrow(/must be a JSON object/);
  });

  it("rejects non-string values", () => {
    expect(() => parseCustomHeaders(JSON.stringify({ "X-Custom-Header": 123 }))).toThrow(
      /only string header values/,
    );
  });

  it("rejects empty header names", () => {
    expect(() => parseCustomHeaders(JSON.stringify({ "": "value" }))).toThrow(/empty header name/);
  });

  it("rejects reserved header names case-insensitively", () => {
    expect(() => parseCustomHeaders(JSON.stringify({ "X-API-Key": "override" }))).toThrow(
      /cannot override reserved header/,
    );
    expect(() => parseCustomHeaders(JSON.stringify({ "Content-Type": "text/plain" }))).toThrow(
      /cannot override reserved header/,
    );
    expect(() => parseCustomHeaders(JSON.stringify({ ACCEPT: "text/plain" }))).toThrow(
      /cannot override reserved header/,
    );
  });
});

